using System.Text.Json;
using Microsoft.AspNetCore.DataProtection;
using Shop.Modules.Credit;
using Shop.SharedKernel;
using Xunit;
namespace Shop.Tests;
public sealed class ChequeReportTests
{
    private static ChequeReportRow Row(string state,string due,string amount="9223372036854775807")=>new("OWNER",new(new string('a',32),"CH-"+new string('A',32),new string('b',32),new string('c',32),1,due,amount,state,"AAAAAAAAAAE=",DateTimeOffset.UtcNow,DateTimeOffset.UtcNow),new(new string('b',32),"OWNER","SM-1","fa","Cancelled",DateTimeOffset.UtcNow.AddDays(-1),DateTimeOffset.UtcNow,"9223372036854775807",1,"AAAAAAAAAAE="));
    [Theory][InlineData("2026-01-01","2027-01-02")][InlineData("2026-02-30","2026-03-01")][InlineData("2026-01-02","2026-01-01")][InlineData("1999-01-01","1999-01-02")][InlineData("2026-1-01","2026-02-01")]
    public void ExplicitCivilRangeIsCanonicalAndAtMost366InclusiveDays(string from,string through)=>Assert.Throws<BusinessException>(()=>ChequeReportRules.Validate(new(from,through,"All")));
    [Fact]public void LeapYear366DayRangeAndEveryExactStateAreAccepted(){foreach(var state in ChequeReportRules.States.Append("All"))ChequeReportRules.Validate(new("2024-01-01","2024-12-31",state));Assert.Throws<BusinessException>(()=>ChequeReportRules.Validate(new("2024-01-01","2024-12-31","received")));}
    [Fact]public void TehranCivilDayFollowsHistoricalOffsetAndMidnight(){Assert.Equal("2026-10-28",ChequeReportRules.Today(DateTimeOffset.Parse("2026-10-27T20:30:00Z")));Assert.Equal("2026-10-27",ChequeReportRules.Today(DateTimeOffset.Parse("2026-10-27T20:29:59Z")));Assert.Equal("2021-07-02",ChequeReportRules.Today(DateTimeOffset.Parse("2021-07-01T19:30:00Z")));}
    [Fact]public void PageAggregateMayExceedSqlLongAndCollectionIsNotHeld(){var rows=new[]{Row("Received","2026-10-27"),Row("Deposited","2026-10-28"),Row("BouncedReported","2026-10-29"),Row("Withdrawn","2026-10-29"),Row("CollectedReported","2026-10-27"),Row("ReturnedToCustomer","2026-10-27")};var t=ChequeReportRules.Totals(rows,new(2026,10,28));Assert.Equal("55340232221128654842",t.AmountRial);Assert.Equal(1,t.OverdueHeldCount);Assert.Equal(1,t.DueTodayHeldCount);Assert.Equal(2,t.FutureHeldCount);Assert.Equal("18446744073709551614",t.FutureHeldRial);Assert.All(t.States,x=>Assert.Equal(1,x.Count));}
    [Fact]public void CursorProtectionIsActorBoundCanonicalAndTamperResistant(){var p=new DataProtectionChequeReportCursorProtection(new EphemeralDataProtectionProvider());var actor=Guid.NewGuid().ToString();var token=p.Protect(actor,"synthetic-no-personal-data");Assert.Equal("synthetic-no-personal-data",p.Unprotect(actor.ToUpperInvariant(),token));Assert.Throws<BusinessException>(()=>p.Unprotect(Guid.NewGuid().ToString(),token));Assert.Throws<BusinessException>(()=>p.Unprotect(actor,token+"="));Assert.Throws<BusinessException>(()=>p.Unprotect(actor,token[..^8]+"AAAAAAAA"));Assert.Throws<BusinessException>(()=>p.Unprotect(actor,new string('A',2049)));}
    [Fact]public void EmptyPageHasExplicitNullAndZeroStringMoney(){var page=new ChequeReportPage(1,new("2026-01-01","2026-01-01","All"),"Asia/Tehran","2026-01-01",DateTimeOffset.UtcNow,DateTimeOffset.UtcNow,DateTimeOffset.UtcNow.AddMinutes(15),[],ChequeReportRules.Totals([],new(2026,1,1)),null);var raw=JsonSerializer.Serialize(page,new JsonSerializerOptions(JsonSerializerDefaults.Web){DefaultIgnoreCondition=System.Text.Json.Serialization.JsonIgnoreCondition.WhenWritingNull});Assert.Contains("\"nextCursor\":null",raw);Assert.Contains("\"amountRial\":\"0\"",raw);Assert.Contains("\"bankVerified\":false",raw);}
}
